class Solution {
    static const int MOD = 1000000007;
    vector<int> masks;
    void build(int pos, int width, const vector<int>& bricks, int mask) {
        if (pos == width) { masks.push_back(mask); return; }
        for (int b : bricks) {
            if (pos + b <= width) {
                int next = mask;
                if (pos + b < width) next |= 1 << (pos + b);
                build(pos + b, width, bricks, next);
            }
        }
    }
public:
    int buildWall(int height, int width, vector<int>& bricks) {
        masks.clear();
        build(0, width, bricks, 0);
        int n = masks.size();
        vector<vector<int>> compatible(n);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if ((masks[i] & masks[j]) == 0) compatible[i].push_back(j);
        vector<int> dp(n, 1);
        for (int row = 1; row < height; ++row) {
            vector<int> next(n);
            for (int i = 0; i < n; ++i)
                for (int j : compatible[i])
                    next[i] = (next[i] + (long long)dp[j]) % MOD;
            dp.swap(next);
        }
        long long answer = 0;
        for (int x : dp) answer = (answer + x) % MOD;
        return answer;
    }
};
